$ cat Native.java
public class Native {
    static List<Deflater> keep = new ArrayList<>();
    public static void main(String[] a) throws Exception {
        boolean end = a[0].equals("end");
        byte[] src = new byte[64 * 1024];
        new Random(1).nextBytes(src);
        for (int i = 0; i < 3000; i++) {
            Deflater d = new Deflater(Deflater.BEST_COMPRESSION);  // zlib 이 네이티브로 잡는다
            d.setInput(src); d.finish();
            d.deflate(new byte[70 * 1024]);
            if (end) d.end();        // 네이티브 자원을 명시적으로 반납
            else keep.add(d);        // 안 하면 쌓인다
        }
        Thread.sleep(30000);
    }
}

